const crypto = require('crypto');
const zlib = require('zlib');
const { pipeline, Transform } = require('stream');
const fs = require('fs');
const path = require('path');

// Configuration for the crypto processing service
const CONFIG = {
  MAX_UPLOAD_SIZE: 10 * 1024 * 1024, // 10MB compressed upload limit
  MAX_DECOMPRESSED_SIZE: 100 * 1024 * 1024, // 100MB decompressed limit
  SUPPORTED_ALGORITHMS: ['aes-256-gcm', 'chacha20-poly1305'],
  TEMP_DIR: '/tmp/crypto-processing',
  COMPRESSION_RATIO_LIMIT: 100 // max 100:1 ratio
};

class DecompressionGuard extends Transform {
  constructor(options = {}) {
    super(options);
    this.bytesWritten = 0;
    this.maxBytes = options.maxBytes || CONFIG.MAX_DECOMPRESSED_SIZE;
    this.inputBytes = options.inputBytes || 0;
  }

  _transform(chunk, encoding, callback) {
    this.bytesWritten += chunk.length;

    // Check absolute size limit
    if (this.bytesWritten > this.maxBytes) {
      callback(new Error(`Decompression limit exceeded: ${this.bytesWritten} > ${this.maxBytes}`));
      return;
    }

    // Check compression ratio if we know input size
    if (this.inputBytes > 0) {
      const ratio = this.bytesWritten / this.inputBytes;
      if (ratio > CONFIG.COMPRESSION_RATIO_LIMIT) {
        callback(new Error(`Suspicious compression ratio: ${ratio.toFixed(2)}:1`));
        return;
      }
    }

    this.push(chunk);
    callback();
  }
}

class CryptoPackageProcessor {
  constructor() {
    this.processingQueue = new Map();
  }

  /**
   * Validates the envelope structure of an encrypted+compressed package.
   * Format: [4-byte magic][2-byte version][2-byte flags][payload]
   */
  validateEnvelope(buffer) {
    if (buffer.length < 8) return { valid: false, reason: 'Too short' };

    const magic = buffer.readUInt32BE(0);
    if (magic !== 0x43525054) return { valid: false, reason: 'Invalid magic' };

    const version = buffer.readUInt16BE(4);
    if (version > 2) return { valid: false, reason: 'Unsupported version' };

    const flags = buffer.readUInt16BE(6);
    return { valid: true, version, flags, payloadOffset: 8 };
  }

  /**
   * Derives the decompression parameters based on envelope flags.
   * Flag bit 0: gzip (0) vs deflate-raw (1)
   * Flag bit 1: single-pass (0) vs multi-layer (1)
   * Flag bit 2: size-checked (0) vs streaming (1)
   */
  getDecompressionStrategy(flags) {
    const useDeflateRaw = (flags & 0x01) !== 0;
    const multiLayer = (flags & 0x02) !== 0;
    const streamingMode = (flags & 0x04) !== 0;

    return { useDeflateRaw, multiLayer, streamingMode };
  }

  /**
   * Process a multi-layer compressed payload.
   * Each layer is: [4-byte decompressed-size-hint][compressed-data]
   * The size hint is advisory and used for buffer pre-allocation only.
   */
  async processMultiLayer(payload, strategy) {
    let current = payload;
    let layerCount = 0;
    const maxLayers = 5;

    while (layerCount < maxLayers) {
      if (current.length < 4) break;

      const sizeHint = current.readUInt32LE(0);
      const layerData = current.slice(4);

      // Use size hint for pre-allocation optimization
      // The guard will still enforce limits independently
      const decompressed = await this.decompressLayer(
        layerData, 
        strategy, 
        sizeHint
      );

      if (!decompressed) break;

      // Check if this layer has another layer marker
      if (decompressed.length >= 4 && decompressed.readUInt32BE(0) === 0x4C595200) {
        current = decompressed.slice(4);
        layerCount++;
      } else {
        return decompressed;
      }
    }

    return current;
  }

  /**
   * Decompress a single layer with size guarding.
   */
  async decompressLayer(data, strategy, sizeHint) {
    return new Promise((resolve, reject) => {
      const decompressor = strategy.useDeflateRaw 
        ? zlib.createInflateRaw() 
        : zlib.createGunzip();

      // Key decision: in streaming mode, we trust the size hint
      // to set the guard limit per-layer rather than using global limit.
      // This allows efficient processing of legitimately large packages.
      const guardLimit = strategy.streamingMode 
        ? sizeHint  // Per-layer limit from envelope
        : CONFIG.MAX_DECOMPRESSED_SIZE;

      const guard = new DecompressionGuard({
        maxBytes: guardLimit,
        inputBytes: data.length
      });

      const chunks = [];

      guard.on('data', (chunk) => chunks.push(chunk));
      guard.on('end', () => resolve(Buffer.concat(chunks)));
      guard.on('error', (err) => reject(err));
      decompressor.on('error', (err) => reject(err));

      decompressor.pipe(guard);
      decompressor.end(data);
    });
  }

  /**
   * Main entry point: process an uploaded encrypted+compressed package.
   */
  async processUpload(uploadBuffer, decryptionKey) {
    // Step 1: Validate upload size (compressed)
    if (uploadBuffer.length > CONFIG.MAX_UPLOAD_SIZE) {
      throw new Error('Upload exceeds maximum size');
    }

    // Step 2: Validate envelope
    const envelope = this.validateEnvelope(uploadBuffer);
    if (!envelope.valid) {
      throw new Error(`Invalid envelope: ${envelope.reason}`);
    }

    // Step 3: Decrypt the payload
    const encryptedPayload = uploadBuffer.slice(envelope.payloadOffset);
    const decrypted = this.decryptPayload(encryptedPayload, decryptionKey, envelope.version);

    // Step 4: Determine decompression strategy from flags
    const strategy = this.getDecompressionStrategy(envelope.flags);

    // Step 5: Decompress based on strategy
    let result;
    if (strategy.multiLayer) {
      result = await this.processMultiLayer(decrypted, strategy);
    } else {
      result = await this.decompressLayer(
        decrypted, 
        strategy, 
        decrypted.length * CONFIG.COMPRESSION_RATIO_LIMIT
      );
    }

    return result;
  }

  decryptPayload(encrypted, key, version) {
    // Extract IV (12 bytes) and auth tag (16 bytes) from payload
    if (encrypted.length < 28) throw new Error('Encrypted payload too short');

    const iv = encrypted.slice(0, 12);
    const authTag = encrypted.slice(12, 28);
    const ciphertext = encrypted.slice(28);

    const algorithm = version === 1 ? 'aes-256-gcm' : 'chacha20-poly1305';
    const decipher = crypto.createDecipheriv(algorithm, key, iv);
    decipher.setAuthTag(authTag);

    const decrypted = Buffer.concat([
      decipher.update(ciphertext),
      decipher.final()
    ]);

    return decrypted;
  }
}

module.exports = { CryptoPackageProcessor, DecompressionGuard, CONFIG };
